    'TemplateText', p_TemplateText_0b6e9a1f92cf,
    'Priority', p_Priority_0b6e9a1f92cf,
    'IsActive', p_IsActive_0b6e9a1f92cf,
    'ID', p_ID_0b6e9a1f92cf
  ));
  ELSE
    PERFORM __mj."spUpdateTemplateContent"(p_TemplateID := p_TemplateID_0b6e9a1f92cf, p_TypeID := p_TypeID_0b6e9a1f92cf, p_TemplateText := p_TemplateText_0b6e9a1f92cf, p_Priority := p_Priority_0b6e9a1f92cf, p_IsActive := p_IsActive_0b6e9a1f92cf, p_ID := p_ID_0b6e9a1f92cf);
  END IF;
END $mj$;

